changeSet.sql:
CREATE FUNCTION update_audio_result_search_vector() RETURNS trigger
LANGUAGE plpgsql AS $$
BEGIN
    NEW.result_search_vector := audio_result_search_vector(NEW.result_data);
    RETURN NEW;
END;
$$

CREATE TRIGGER refresh_audio_result_search_vector
BEFORE INSERT OR UPDATE OF result_data ON audio_uploads
FOR EACH ROW EXECUTE FUNCTION update_audio_result_search_vector();

UPDATE audio_uploads
SET result_search_vector = audio_result_search_vector(result_data)
WHERE result_data IS NOT NULL;

CREATE INDEX idx_audio_uploads_result_search
ON audio_uploads USING GIN (result_search_vector);

rollback.sql:
DROP TRIGGER refresh_audio_result_search_vector ON audio_uploads;
DROP FUNCTION update_audio_result_search_vector();
DROP FUNCTION audio_result_search_vector(bytea);
